import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"HTTPS and Certificates","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/https.md","filePath":"en/guide/https.md","lastUpdated":1786689844000}'),r={name:"en/guide/https.md"};function n(o,e,c,d,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="https-and-certificates" tabindex="-1">HTTPS and Certificates <a class="header-anchor" href="#https-and-certificates" aria-label="Permalink to &quot;HTTPS and Certificates&quot;">​</a></h1><h2 id="issuance-types" tabindex="-1">Issuance Types <a class="header-anchor" href="#issuance-types" aria-label="Permalink to &quot;Issuance Types&quot;">​</a></h2><p>The certificate tool (<code>zviewer-cert</code>, source code at <code>scripts/generate-cert.js</code>) automatically selects the issuance method based on the address type:</p><table tabindex="0"><thead><tr><th>Address Type</th><th>Certificate</th><th>Description</th></tr></thead><tbody><tr><td><code>localhost</code></td><td>Self-signed certificate</td><td>SAN includes <code>localhost</code>, <code>127.0.0.1</code>, <code>::1</code>, valid for 10 years</td></tr><tr><td>Domain (e.g., <code>example.com</code>)</td><td><strong>Let&#39;s Encrypt trusted CA certificate</strong></td><td>Automatically applied via the built-in ACME client; no browser warnings</td></tr><tr><td>Public IP (e.g., <code>1.2.3.4</code>)</td><td><strong>Let&#39;s Encrypt trusted CA certificate</strong></td><td>Supports issuing Let&#39;s Encrypt trusted certificates for public IPs</td></tr></tbody></table><blockquote><p>Certificate issuance is pure Node.js (no openssl required), based on the built-in ACME v2 (RFC 8555) HTTP-01 client, with <code>node-forge</code> as the only dependency.</p></blockquote><h2 id="command-line-issuance" tabindex="-1">Command-line Issuance <a class="header-anchor" href="#command-line-issuance" aria-label="Permalink to &quot;Command-line Issuance&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Domain -&gt; automatically apply for a Let&#39;s Encrypt trusted certificate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Public IP -&gt; automatically apply for a Let&#39;s Encrypt trusted certificate (IP supported)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.2.3.4</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Force re-issuance</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>In HTTPS mode, the backend also serves frontend static pages. Visit <code>https://localhost:3333</code>.</p><h2 id="prerequisites-for-domain-let-s-encrypt-certificate" tabindex="-1">Prerequisites for Domain Let&#39;s Encrypt Certificate <a class="header-anchor" href="#prerequisites-for-domain-let-s-encrypt-certificate" aria-label="Permalink to &quot;Prerequisites for Domain Let&#39;s Encrypt Certificate&quot;">​</a></h2><ol><li>The domain must be resolved to the machine&#39;s public IP.</li><li>Port <strong>80</strong> on the machine must be available and allowed through the firewall/security group (ACME HTTP-01 verification).</li><li>The production environment has rate limits (5 certificates per domain per week). Use <code>--staging</code> for testing.</li></ol><h2 id="certificate-file-location" tabindex="-1">Certificate File Location <a class="header-anchor" href="#certificate-file-location" aria-label="Permalink to &quot;Certificate File Location&quot;">​</a></h2><p>Certificate files are located in <code>config/ssl/</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Content</th></tr></thead><tbody><tr><td><code>cert.pem</code></td><td>Certificate chain</td></tr><tr><td><code>key.pem</code></td><td>Private key</td></tr><tr><td><code>acme-account.key</code></td><td>ACME account key</td></tr></tbody></table><h2 id="related-environment-variables" tabindex="-1">Related Environment Variables <a class="header-anchor" href="#related-environment-variables" aria-label="Permalink to &quot;Related Environment Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>HTTPS=true</code></td><td>Enable HTTPS mode and serve frontend static files</td></tr><tr><td><code>SSL_CERT_PATH</code></td><td>Certificate path</td></tr><tr><td><code>SSL_KEY_PATH</code></td><td>Private key path</td></tr></tbody></table><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="self-signed-certificate-shows-not-secure-in-browser" tabindex="-1">Self-signed Certificate Shows &quot;Not Secure&quot; in Browser <a class="header-anchor" href="#self-signed-certificate-shows-not-secure-in-browser" aria-label="Permalink to &quot;Self-signed Certificate Shows &quot;Not Secure&quot; in Browser&quot;">​</a></h3><p><code>localhost</code> and public IPs use self-signed certificates, causing browsers to warn &quot;The certificate authority is not trusted&quot;. Solutions:</p><ul><li>Import <code>config/ssl/cert.pem</code> into the client&#39;s &quot;Trusted Root Certification Authorities&quot;; or</li><li>Use a domain name and apply for a trusted certificate via Let&#39;s Encrypt.</li></ul><h3 id="reverse-proxy-scenario" tabindex="-1">Reverse Proxy Scenario <a class="header-anchor" href="#reverse-proxy-scenario" aria-label="Permalink to &quot;Reverse Proxy Scenario&quot;">​</a></h3><p>If using Nginx / Caddy or another reverse proxy to terminate TLS, keep the backend in HTTP mode. There is no need to issue certificates within ZViewer. Make sure to configure WebSocket upgrade headers correctly (see <a href="/en/guide/faq#websocket-connection-failure">FAQ</a>).</p>`,21)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
